	private RhythmVoiceModel() {}

	public static boolean isReady() {
		return HIDDEN > 0 && W1.length == HIDDEN * INPUTS && MEAN.length == INPUTS;
	}

	public static double probability(float[] x) {
		if (!isReady()) return Double.NaN;
		double out = B2;
		for (int h = 0; h < HIDDEN; h++) {
			double acc = B1[h];
			int base = h * INPUTS;
			for (int i = 0; i < INPUTS; i++) acc += W1[base + i] * ((x[i] - MEAN[i]) * SCALE[i]);
			out += W2[h] * Math.tanh(acc);
		}
		return 1.0 / (1.0 + Math.exp(-out));
	}
